import { defineExperience, startExperience } from '@signal-lab/experience-sdk';
import { calculateFermentation, type Inputs } from './director';
import { FermentationScene } from './scene';

let root: HTMLElement | null = null;
let scene: FermentationScene | null = null;
let inputs: Inputs = { temperature: 24, hydration: 68, hours: 8 };
const disposers: Array<() => void> = [];

const presets: Record<string, Inputs> = {
  slow: { temperature: 19, hydration: 66, hours: 4 },
  balanced: { temperature: 24, hydration: 68, hours: 8 },
  quick: { temperature: 29, hydration: 74, hours: 10 }
};

function writeText(selector: string, value: string): void {
  const element = root?.querySelector(selector);
  if (element) element.textContent = value;
}

function progressForHours(hours: number): number {
  return Math.max(0, Math.min(1, (hours - 2) / 14));
}

function sendProgress(hours: number): void {
  postMessage({ type: 'signal-lab:preview-progress', progress: progressForHours(hours) }, location.origin);
}

function render(): void {
  if (!root || !scene) return;
  const state = calculateFermentation(inputs);
  scene.render(state);
  root.querySelectorAll<HTMLInputElement>('input[data-key]').forEach((input) => {
    input.value = String(inputs[input.dataset.key as keyof Inputs]);
    input.style.setProperty('--value', `${((Number(input.value) - Number(input.min)) / (Number(input.max) - Number(input.min))) * 100}%`);
  });
  writeText('[data-value="temperature"]', `${inputs.temperature}°C`);
  writeText('[data-value="hydration"]', `${inputs.hydration}%`);
  writeText('[data-value="hours"]', `${Number.isInteger(inputs.hours) ? inputs.hours : inputs.hours.toFixed(1)} 小时`);
  writeText('[data-phase-label]', state.phaseLabel);
  writeText('[data-phase-note]', state.phaseNote);
  writeText('[data-recommendation]', state.recommendation);
  writeText('[data-volume]', `${state.volume}%`);
  writeText('[data-bubbles]', `${state.bubbles} / dm²`);
  writeText('[data-tension]', `${state.tension} / 100`);
  writeText('[data-progress]', `${Math.round(state.maturity * 100)}%`);
  writeText('[data-scroll-hour]', `${Number.isInteger(inputs.hours) ? inputs.hours : inputs.hours.toFixed(1)}h`);
  root.dataset.phase = state.phase;
}

function mount(context: Parameters<ReturnType<typeof defineExperience>['mount']>[0]): void {
  root = document.createElement('main');
  root.className = `fermentation-workspace${context.reducedMotion ? ' reduced-motion' : ''}`;
  root.innerHTML = `
    <header class="topbar">
      <a class="brand" href="#workspace" aria-label="发酵观察工作台首页"><span class="brand-mark">F</span><span>FERMENT / 发酵观察</span></a>
      <div class="lesson-note"><span></span>社区烘焙课 · 教学估算</div>
    </header>
    <section class="workspace" id="workspace" aria-labelledby="page-title">
      <div class="visual-column">
        <div class="intro-block">
          <p class="eyebrow">同一罐面团 · 三种成熟状态</p>
          <h1 id="page-title">看见面团<br>如何醒来</h1>
          <p>拖动参数，透明发酵罐会从建立、活跃到成熟连续变化。视觉、数值和建议来自同一组教学估算。</p>
        </div>
        <div class="jar-field" aria-label="透明发酵罐状态视图">
          <div class="sun-wash" aria-hidden="true"></div>
          <div class="jar-visual" role="img" aria-label="同一只透明发酵罐随参数改变呈现不同成熟状态">
            <span class="jar-frame jar-early"></span><span class="jar-frame jar-active"></span><span class="jar-frame jar-mature"></span><span class="jar-shadow" aria-hidden="true"></span>
          </div>
          <div class="state-marker"><span>当前状态</span><strong data-phase-label>活跃期</strong><small data-phase-note>气泡网络已经清晰，体积与表面张力处于可观察窗口。</small></div>
          <div class="metric metric-volume"><span>预计体积</span><strong data-volume>158%</strong></div>
          <div class="metric metric-bubbles"><span>气泡密度</span><strong data-bubbles>68 / dm²</strong></div>
          <div class="scroll-cue" aria-hidden="true">
            <div><span>SCROLL / 滚动推演</span><strong data-scroll-hour>8h</strong></div>
            <div class="scroll-track"><i></i></div>
            <small>向下增加发酵时间 · 向上回看早期状态</small>
          </div>
        </div>
      </div>
      <aside class="control-panel" aria-label="发酵参数与教学结果">
        <div class="panel-heading"><p class="eyebrow">建立你的烘焙计划</p><span class="progress-ring" data-progress>55%</span></div>
        <div class="preset-row" aria-label="发酵预设"><button type="button" data-preset="slow">慢速风味</button><button type="button" class="selected" data-preset="balanced">均衡观察</button><button type="button" data-preset="quick">当天快发</button></div>
        <div class="sliders">
          <label><span><b>室温</b><output data-value="temperature">24°C</output></span><input type="range" min="18" max="30" value="24" step="1" data-key="temperature"><small>影响酵母活性与变化速度</small></label>
          <label><span><b>面团含水率</b><output data-value="hydration">68%</output></span><input type="range" min="58" max="82" value="68" step="1" data-key="hydration"><small>影响气泡延展与表面张力</small></label>
          <label><span><b>发酵时间</b><output data-value="hours">8 小时</output></span><input type="range" min="2" max="16" value="8" step="0.5" data-key="hours"><small>鼠标滚轮也会同步改变这个参数</small></label>
        </div>
        <div class="reading" aria-live="polite"><div><span>表面张力</span><strong data-tension>67 / 100</strong></div><p data-recommendation>现在适合练习折叠、判断弹性，并记录气泡分布。</p><small>教学估算 · 实际发酵仍需结合触感、气味与环境判断</small></div>
        <button type="button" class="save-plan"><span>保存这份烘焙计划</span><span aria-hidden="true">→</span></button>
        <p class="save-status" role="status" aria-live="polite"></p>
      </aside>
    </section>`;
  context.container.appendChild(root);
  const visual = root.querySelector<HTMLElement>('.jar-field');
  if (!visual) throw new Error('发酵罐视觉区域未挂载。');
  scene = new FermentationScene(visual);

  root.querySelectorAll<HTMLInputElement>('input[data-key]').forEach((input) => {
    const handler = () => {
      const key = input.dataset.key as keyof Inputs;
      inputs = { ...inputs, [key]: Number(input.value) };
      root?.querySelectorAll('[data-preset]').forEach((button) => button.classList.remove('selected'));
      render();
      if (key === 'hours') sendProgress(inputs.hours);
    };
    input.addEventListener('input', handler); disposers.push(() => input.removeEventListener('input', handler));
  });
  root.querySelectorAll<HTMLButtonElement>('[data-preset]').forEach((button) => {
    const handler = () => {
      inputs = presets[button.dataset.preset || 'balanced'];
      root?.querySelectorAll('[data-preset]').forEach((item) => item.classList.toggle('selected', item === button));
      render();
      sendProgress(inputs.hours);
    };
    button.addEventListener('click', handler); disposers.push(() => button.removeEventListener('click', handler));
  });
  const save = root.querySelector<HTMLButtonElement>('.save-plan');
  const saveHandler = () => {
    if (!root || !save) return;
    const state = calculateFermentation(inputs);
    save.classList.add('saved'); save.querySelector('span')!.textContent = '计划已保存';
    writeText('.save-status', `${state.phaseLabel} · ${inputs.temperature}°C · ${inputs.hydration}% · ${inputs.hours} 小时`);
  };
  save?.addEventListener('click', saveHandler); if (save) disposers.push(() => save.removeEventListener('click', saveHandler));
  render();
}

function update(frame: Parameters<ReturnType<typeof defineExperience>['update']>[0]): void {
  if (!root || frame.viewport.width <= 760) return;
  const nextHours = Math.round((2 + frame.progress * 14) * 2) / 2;
  root.style.setProperty('--scroll-progress', frame.progress.toFixed(4));
  if (Math.abs(nextHours - inputs.hours) < .01) return;
  inputs = { ...inputs, hours: nextHours };
  const selected = root.querySelector<HTMLButtonElement>('[data-preset].selected');
  if (selected) {
    const preset = presets[selected.dataset.preset || 'balanced'];
    if (Math.abs(preset.hours - nextHours) > .51) selected.classList.remove('selected');
  }
  render();
}
function resize(): void {}
function dispose(): void { disposers.splice(0).forEach((disposeListener) => disposeListener()); scene?.dispose(); scene = null; root?.remove(); root = null; }

startExperience(defineExperience({ mount, update, resize, dispose }));

import type { FermentationState } from './director';

export class FermentationScene {
  private frames: HTMLElement[];
  private root: HTMLElement;

  constructor(root: HTMLElement) {
    this.root = root;
    this.frames = Array.from(root.querySelectorAll<HTMLElement>('.jar-frame'));
  }

  render(state: FermentationState): void {
    const p = state.maturity;
    const clamp = (value: number) => Math.max(0, Math.min(1, value));
    const early = clamp((.38 - p) / .16);
    const mature = clamp((p - .54) / .16);
    const weights = [early, clamp(1 - early - mature), mature];
    const total = weights.reduce((sum, value) => sum + value, 0) || 1;
    const activeIndex = state.phase === 'early' ? 0 : state.phase === 'active' ? 1 : 2;
    this.frames.forEach((frame, index) => {
      frame.style.opacity = String(weights[index] / total);
      frame.setAttribute('aria-hidden', index === activeIndex ? 'false' : 'true');
    });
    this.root.dataset.phase = state.phase;
    this.root.style.setProperty('--maturity', state.maturity.toFixed(3));
    this.root.style.setProperty('--warmth', state.warmth.toFixed(3));
    const workspace = this.root.closest<HTMLElement>('.fermentation-workspace');
    workspace?.style.setProperty('--maturity', state.maturity.toFixed(3));
    workspace?.style.setProperty('--warmth', state.warmth.toFixed(3));
  }

  dispose(): void {
    this.frames.forEach((frame) => frame.removeAttribute('style'));
    this.frames = [];
  }
}

export type Inputs = { temperature: number; hydration: number; hours: number };

export type FermentationState = {
  maturity: number;
  phase: 'early' | 'active' | 'mature';
  phaseLabel: string;
  phaseNote: string;
  volume: number;
  bubbles: number;
  tension: number;
  warmth: number;
  recommendation: string;
};

const clamp = (value: number, min = 0, max = 1) => Math.min(max, Math.max(min, value));

export function calculateFermentation(inputs: Inputs): FermentationState {
  const temperatureFactor = clamp((inputs.temperature - 17) / 15, .08, 1.08);
  const timeFactor = clamp((inputs.hours - 1) / 15, 0, 1);
  const hydrationFactor = clamp((inputs.hydration - 55) / 28, .05, 1);
  const maturity = clamp(timeFactor * .62 + temperatureFactor * .27 + hydrationFactor * .11);
  const phase = maturity < .36 ? 'early' : maturity < .66 ? 'active' : 'mature';
  const volume = Math.round(100 + maturity * 92);
  const bubbles = Math.round(12 + maturity * 76 + hydrationFactor * 12);
  const tension = Math.round(clamp(.92 - hydrationFactor * .38 + maturity * .08, .28, .94) * 100);

  if (phase === 'early') {
    return { maturity, phase, volume, bubbles, tension, warmth: temperatureFactor, phaseLabel: '建立期', phaseNote: '气泡正在形成，面团仍以紧实和轻微隆起为主。', recommendation: '继续等待，并在体积接近 150% 时重新观察。' };
  }
  if (phase === 'active') {
    return { maturity, phase, volume, bubbles, tension, warmth: temperatureFactor, phaseLabel: '活跃期', phaseNote: '气泡网络已经清晰，体积与表面张力处于可观察窗口。', recommendation: '现在适合练习折叠、判断弹性，并记录气泡分布。' };
  }
  return { maturity, phase, volume, bubbles, tension, warmth: temperatureFactor, phaseLabel: '成熟期', phaseNote: '面团接近峰值，气泡密集且顶部隆起更明显。', recommendation: inputs.temperature >= 28 || inputs.hours >= 14 ? '建议尽快进入整形，避免继续发酵造成结构回落。' : '已接近理想成熟窗口，可以准备整形与烘烤。' };
}

:root {
  color-scheme: light;
  --ink: #2d2a23;
  --muted: #746d60;
  --line: rgba(73, 63, 45, 0.16);
  --paper: #f7f1e5;
  --cream: #fffaf0;
  --amber: #b16c24;
  --amber-deep: #7d4819;
  --sage: #6f765e;
}
* {
  box-sizing: border-box;
}
html {
  background: #eee5d6;
  scroll-behavior: smooth;
}
body {
  margin: 0;
  min-width: 320px;
  background: #eee5d6;
  color: var(--ink);
  font-family: Inter, "Noto Sans SC", "Microsoft YaHei", system-ui, sans-serif;
}
.generated-loading {
  display: none !important;
}
.generated-canvas {
  display: none !important;
}
.fermentation-workspace {
  --maturity: 0.5;
  --warmth: 0.5;
  --scroll-progress: 0;
  min-height: 100dvh;
  overflow: hidden;
  background:
    radial-gradient(
      circle at 34% 18%,
      rgba(255, 255, 255, 0.94),
      transparent 29%
    ),
    linear-gradient(115deg, #f7f1e5 0%, #eee3d2 58%, #e2d1b9 100%);
  position: relative;
}
.fermentation-workspace:before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.26;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.13'/%3E%3C/svg%3E");
}
.topbar {
  height: 68px;
  padding: 0 clamp(22px, 4vw, 64px);
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--line);
  position: relative;
  z-index: 10;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--ink);
  text-decoration: none;
  font-size: 12px;
  font-weight: 750;
  letter-spacing: 0.12em;
}
.brand-mark {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border: 1px solid rgba(48, 44, 35, 0.35);
  border-radius: 50%;
  font-family: Georgia, serif;
  font-size: 15px;
}
.lesson-note {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 11px;
  letter-spacing: 0.08em;
}
.lesson-note span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #c98739;
  box-shadow: 0 0 0 4px rgba(201, 135, 57, 0.12);
}
.workspace {
  position: relative;
  z-index: 1;
  min-height: calc(100dvh - 68px);
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(350px, 0.68fr);
  gap: clamp(18px, 3vw, 52px);
  padding: clamp(18px, 3.2vh, 34px) clamp(22px, 4vw, 64px)
    clamp(22px, 3.4vh, 38px);
}
.visual-column {
  position: relative;
  min-height: 680px;
}
.intro-block {
  position: absolute;
  z-index: 6;
  left: 0;
  top: 3%;
  width: min(39%, 390px);
}
.eyebrow {
  margin: 0;
  color: #8c5924;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.17em;
  text-transform: uppercase;
}
.intro-block h1 {
  margin: 15px 0 15px;
  font-family: Georgia, "Noto Serif SC", serif;
  font-size: clamp(43px, 4.8vw, 70px);
  font-weight: 450;
  line-height: 0.96;
  letter-spacing: -0.055em;
}
.intro-block > p:last-child {
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.75;
  max-width: 31em;
}
.jar-field {
  position: absolute;
  inset: 0;
  isolation: isolate;
  cursor: ns-resize;
}
.sun-wash {
  position: absolute;
  left: 19%;
  top: -16%;
  width: 80%;
  height: 108%;
  background: radial-gradient(
    ellipse at 54% 40%,
    rgba(255, 245, 215, 0.94),
    rgba(223, 178, 111, 0.17) 41%,
    transparent 68%
  );
  filter: blur(14px);
  opacity: calc(0.72 + var(--warmth) * 0.18);
}
.jar-visual {
  position: absolute;
  z-index: 2;
  left: 50%;
  top: 47%;
  width: min(29vw, 305px);
  aspect-ratio: 1/2;
  transform: translate(-46%, -46%);
  filter: drop-shadow(0 34px 30px rgba(74, 53, 29, 0.23));
  transition: filter 0.45s ease;
}
.jar-frame {
  position: absolute;
  inset: 0;
  background-image: url("/creative-assets/r68-fermentation-jar-three-state-v1.png");
  background-size: 300% 100%;
  background-repeat: no-repeat;
  transition:
    opacity 0.55s cubic-bezier(0.2, 0.75, 0.25, 1),
    transform 0.55s ease;
}
.jar-early {
  background-position: left center;
}
.jar-active {
  background-position: center center;
}
.jar-mature {
  background-position: right center;
}
.jar-shadow {
  position: absolute;
  z-index: -1;
  left: 10%;
  right: 10%;
  bottom: -3%;
  height: 7%;
  border-radius: 50%;
  background: rgba(68, 49, 28, 0.26);
  filter: blur(13px);
}
.jar-field[data-phase="early"] .jar-visual {
  filter: drop-shadow(0 26px 28px rgba(83, 67, 43, 0.19));
}
.jar-field[data-phase="mature"] .jar-visual {
  filter: drop-shadow(0 34px 34px rgba(139, 83, 23, 0.28));
}
.state-marker {
  position: absolute;
  z-index: 4;
  left: 3%;
  bottom: 8%;
  width: 31%;
  padding: 17px 0 0 18px;
  border-left: 1px solid rgba(92, 70, 42, 0.42);
}
.state-marker:before {
  content: "";
  position: absolute;
  left: -3px;
  top: -3px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #a96924;
}
.state-marker span,
.metric span {
  display: block;
  color: var(--muted);
  font-size: 9px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}
.state-marker strong {
  display: block;
  margin: 6px 0 5px;
  font-family: Georgia, "Noto Serif SC", serif;
  font-size: 26px;
  font-weight: 500;
}
.state-marker small {
  display: block;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.65;
}
.metric {
  position: absolute;
  z-index: 4;
  min-width: 112px;
  padding: 10px 12px;
  border-top: 1px solid rgba(89, 72, 47, 0.34);
  background: rgba(250, 244, 232, 0.5);
  backdrop-filter: blur(8px);
}
.metric strong {
  display: block;
  margin-top: 5px;
  font-family: Georgia, serif;
  font-size: 19px;
  font-weight: 500;
}
.metric-volume {
  right: 7%;
  top: 20%;
}
.metric-bubbles {
  right: 1%;
  bottom: 18%;
}
.scroll-cue {
  position: absolute;
  z-index: 6;
  left: 50%;
  bottom: 2.5%;
  width: min(300px, 38%);
  transform: translateX(-50%);
  color: #716654;
  pointer-events: none;
}
.scroll-cue > div:first-child {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 8px;
}
.scroll-cue span,
.scroll-cue small {
  font-size: 8px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}
.scroll-cue strong {
  color: var(--amber-deep);
  font-family: Georgia, serif;
  font-size: 15px;
  font-weight: 500;
}
.scroll-track {
  position: relative;
  height: 2px;
  margin-bottom: 8px;
  background: rgba(83, 70, 50, 0.16);
}
.scroll-track::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: calc(var(--scroll-progress) * 100%);
  background: var(--amber);
}
.scroll-track i {
  position: absolute;
  top: 50%;
  left: calc(var(--scroll-progress) * 100%);
  width: 12px;
  height: 12px;
  border: 3px solid #f8f0e2;
  border-radius: 50%;
  background: var(--amber);
  box-shadow: 0 0 0 1px rgba(135, 82, 29, 0.45);
  transform: translate(-50%, -50%);
}
.scroll-cue small {
  display: block;
  color: #938977;
  letter-spacing: 0.03em;
  text-transform: none;
}
.control-panel {
  align-self: stretch;
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: clamp(22px, 3vw, 40px);
  border: 1px solid rgba(77, 64, 44, 0.16);
  border-radius: 3px;
  background: rgba(255, 251, 243, 0.78);
  box-shadow: 0 24px 70px rgba(79, 56, 25, 0.08);
  backdrop-filter: blur(18px);
  position: relative;
}
.panel-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--line);
}
.progress-ring {
  display: grid;
  place-items: center;
  width: 47px;
  height: 47px;
  border-radius: 50%;
  font-family: Georgia, serif;
  font-size: 12px;
  background:
    radial-gradient(circle, #f8f1e5 0 61%, transparent 64%),
    conic-gradient(
      var(--amber) calc(var(--maturity) * 1turn),
      rgba(123, 105, 78, 0.12) 0
    );
}
.preset-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  margin: 22px 0;
}
.preset-row button {
  min-height: 39px;
  padding: 7px;
  border: 1px solid var(--line);
  border-radius: 2px;
  background: transparent;
  color: #60584d;
  font: inherit;
  font-size: 11px;
  cursor: pointer;
  transition:
    background 0.2s,
    color 0.2s,
    border-color 0.2s;
}
.preset-row button:hover,
.preset-row button:focus-visible {
  border-color: #9b6a35;
  outline: none;
}
.preset-row button.selected {
  background: #37362e;
  border-color: #37362e;
  color: #fff;
}
.sliders {
  display: grid;
  gap: 19px;
}
.sliders label {
  display: block;
}
.sliders label > span {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 8px;
}
.sliders b {
  font-size: 13px;
  font-weight: 650;
}
.sliders output {
  color: var(--amber-deep);
  font-family: Georgia, serif;
  font-size: 17px;
}
.sliders small {
  display: block;
  margin-top: 6px;
  color: #91887a;
  font-size: 9px;
}
.sliders input {
  --value: 50%;
  width: 100%;
  height: 16px;
  margin: 0;
  appearance: none;
  background: transparent;
  cursor: pointer;
}
.sliders input::-webkit-slider-runnable-track {
  height: 3px;
  background: linear-gradient(
    to right,
    var(--amber) var(--value),
    rgba(70, 61, 48, 0.15) var(--value)
  );
  border-radius: 99px;
}
.sliders input::-webkit-slider-thumb {
  appearance: none;
  width: 16px;
  height: 16px;
  margin-top: -6.5px;
  border: 4px solid #faf3e7;
  border-radius: 50%;
  background: var(--amber);
  box-shadow: 0 0 0 1px #9c6a32;
}
.sliders input:focus-visible {
  outline: 2px solid #8b5b26;
  outline-offset: 6px;
}
.reading {
  margin-top: auto;
  padding: 18px 0 16px;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.reading div {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}
.reading div span {
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 0.08em;
}
.reading div strong {
  font-family: Georgia, serif;
  font-size: 18px;
  font-weight: 500;
}
.reading p {
  min-height: 2.8em;
  margin: 14px 0 9px;
  font-family: Georgia, "Noto Serif SC", serif;
  font-size: 15px;
  line-height: 1.48;
}
.reading > small {
  display: block;
  color: #948a7b;
  font-size: 9px;
  line-height: 1.5;
}
.save-plan {
  width: 100%;
  min-height: 52px;
  margin-top: 17px;
  padding: 0 19px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border: 0;
  border-radius: 2px;
  background: #a96622;
  color: #fff;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  box-shadow: 0 12px 24px rgba(133, 78, 25, 0.16);
  transition:
    background 0.2s,
    transform 0.2s;
}
.save-plan:hover {
  background: #8e551d;
  transform: translateY(-1px);
}
.save-plan:focus-visible {
  outline: 3px solid rgba(142, 85, 29, 0.34);
  outline-offset: 3px;
}
.save-plan.saved {
  background: #65705a;
}
.save-status {
  min-height: 16px;
  margin: 7px 0 0;
  color: #6a735e;
  font-size: 9px;
  text-align: center;
}
.reduced-motion * {
  transition-duration: 0s !important;
  scroll-behavior: auto !important;
}
@media (max-width: 980px) {
  .workspace {
    grid-template-columns: 1fr minmax(320px, 0.72fr);
    gap: 16px;
    padding-inline: 22px;
  }
  .visual-column {
    min-height: 650px;
  }
  .intro-block {
    width: 45%;
  }
  .jar-visual {
    width: min(34vw, 290px);
    left: 57%;
  }
  .metric-volume {
    right: 0;
  }
  .metric-bubbles {
    right: 0;
  }
  .control-panel {
    padding: 24px;
  }
  .state-marker {
    width: 40%;
  }
}
@media (max-width: 760px) {
  .fermentation-workspace {
    overflow: auto;
  }
  .jar-field {
    cursor: default;
  }
  .scroll-cue {
    display: none;
  }
  .topbar {
    height: 58px;
    padding: 0 16px;
  }
  .lesson-note {
    font-size: 9px;
  }
  .brand > span:last-child {
    font-size: 10px;
  }
  .workspace {
    min-height: auto;
    display: block;
    padding: 16px;
  }
  .visual-column {
    min-height: 660px;
  }
  .intro-block {
    position: relative;
    top: auto;
    width: 100%;
    padding-right: 6%;
  }
  .intro-block h1 {
    font-size: clamp(42px, 13vw, 60px);
    max-width: 8em;
  }
  .intro-block > p:last-child {
    max-width: 34em;
  }
  .jar-field {
    top: 170px;
    height: 490px;
  }
  .jar-visual {
    left: 50%;
    top: 49%;
    width: min(52vw, 235px);
    transform: translate(-50%, -47%);
  }
  .state-marker {
    left: 0;
    bottom: 1%;
    width: 48%;
  }
  .metric-volume {
    right: 0;
    top: 9%;
  }
  .metric-bubbles {
    right: 0;
    bottom: 7%;
  }
  .control-panel {
    margin-top: 12px;
    min-height: 640px;
    padding: 24px 18px 20px;
  }
  .reading {
    margin-top: 28px;
  }
  .save-plan {
    min-height: 56px;
  }
}
@media (max-width: 430px) {
  .lesson-note {
    max-width: 125px;
    text-align: right;
  }
  .visual-column {
    min-height: 620px;
  }
  .jar-field {
    top: 175px;
    height: 445px;
  }
  .jar-visual {
    width: 54vw;
  }
  .metric {
    min-width: 104px;
    padding: 8px 9px;
  }
  .metric strong {
    font-size: 16px;
  }
  .state-marker {
    width: 54%;
  }
  .preset-row button {
    font-size: 10px;
    padding-inline: 3px;
  }
  .control-panel {
    min-height: 610px;
  }
  .intro-block h1 {
    letter-spacing: -0.06em;
  }
}
@media (prefers-reduced-motion: reduce) {
  * {
    scroll-behavior: auto !important;
  }
  .jar-frame,
  .save-plan,
  .preset-row button {
    transition: none !important;
  }
}
